-- Every material at the stock the demo was written with.
do $$
declare
  wrong text;
begin
  select string_agg(format('%s has %s, expected %s', i.id, i.quantity_available, d.quantity), '; ')
    into wrong
    from (values
      ('inv-led-bulb', 452.0),
      ('inv-pvc-pipe', 12.0),
      ('inv-hvac-filter', 128.0),
      ('inv-romex-wire', 34.0),
      ('inv-white-paint', 5.0),
      ('inv-socket-plate', 40.0),
      ('inv-insulation-tape', 2.0),
      ('inv-floor-sealant', 6.0)
    ) d (id, quantity)
    left join public.inventory_items i using (id)
   where i.quantity_available is distinct from d.quantity;
  if wrong is not null then
    raise exception 'The seed ledger does not add up: %', wrong;
  end if;
end $$;

